import type { Theme, ThemeOptions } from "@types";

import { isNullish } from "@system";
import { merge } from "lodash-es";

import generateCSSVars from "./generate-css-vars";
import { CssSizeUnitConverter } from "./css-transforms";

export function handleThemeMerge<T extends Theme>(
  baseTheme: T | ThemeOptions<T>,
  customTheme: ThemeOptions<T>,
): T {
  const newThemeOptions = {
    useCSSVariables: !isNullish(customTheme.useCSSVariables) ? customTheme.useCSSVariables : true,
    ...customTheme,
  };

  const mergedTheme = merge({}, baseTheme, newThemeOptions);

  if (mergedTheme.useCSSVariables) {
    mergedTheme.cssVariables = (mergedTheme.cssVariables || "") + generateCSSVars(mergedTheme);
  } else {
    delete mergedTheme.cssVariables;
  }

  const { toRem, toPx, resolveFontSize } = CssSizeUnitConverter(mergedTheme as T);
  mergedTheme.toRem = toRem;
  mergedTheme.toPx = toPx;
  mergedTheme.resolveFontSize = resolveFontSize;

  mergedTheme.getSpacing = (multiplier: number): string =>
    `calc(${toRem(mergedTheme.spacing?.[8] || 8)} * ${multiplier})`;

  return mergedTheme as T;
}

export const createThemeWithoutDefaultMerge = <T extends Theme>(
  themeConfig: T | ThemeOptions<T>,
  newThemeConfig?: ThemeOptions<T>,
): T => {
  if (newThemeConfig) {
    return handleThemeMerge(themeConfig, newThemeConfig);
  }

  return handleThemeMerge({} as ThemeOptions<T>, themeConfig as ThemeOptions<T>);
};
